def t(key: str, lang: str | None, **kwargs) -> str:
    """Translate with English fallback."""
    entry = MESSAGES.get(key) or LABELS.get(key)
    if entry is None:
        raise KeyError(key)
    text = entry.get(lang or "en") or entry["en"]
    return text.format(**kwargs) if kwargs else text
